// Cocos 3.8's npm resolver treats fflate's .js ESM entry as CJS. Keep a pinned,
// auditable ESM/TS copy so Creator can compile and tree-shake it correctly.
const fs=require('node:fs'),crypto=require('node:crypto');
const pkg=require('../node_modules/fflate/package.json'),input='node_modules/fflate/esm/browser.js',license=fs.readFileSync('node_modules/fflate/LICENSE','utf8');
const code=fs.readFileSync(input,'utf8').replace(/\/\/# sourceMappingURL=.*$/mg,'');
const header='// @ts-nocheck\n// Generated by scripts/vendor-inflate.cjs from fflate '+pkg.version+'\n// https://github.com/101arrowz/fflate\n/*\n'+license+'\n*/\n';
fs.mkdirSync('assets/scripts/vendor',{recursive:true});fs.writeFileSync('assets/scripts/vendor/fflate.ts',header+code);
fs.writeFileSync('art/runtime-grunts/codec-source.json',JSON.stringify({package:'fflate',version:pkg.version,source:input,sha256:crypto.createHash('sha256').update(code).digest('hex'),license:'MIT',generated:'assets/scripts/vendor/fflate.ts'},null,2)+'\n');
